WITH filtered_stores AS (SELECT *, CAST(sqft AS STRING) AS sqft_num FROM stores WHERE store_name LIKE '%Kios%' AND city IN ('London', 'Bangkok') AND store_name LIKE 'Ai%'), summary AS (SELECT city, DATE_TRUNC('MONTH', opened_date) AS opened_month, COUNT(sqft) AS sqft_count, ROUND(STDDEV(sqft), 2) AS stddev_sqft FROM filtered_stores GROUP BY city, DATE_TRUNC('MONTH', opened_date)) SELECT * FROM summary WHERE sqft_count > 4 ORDER BY stddev_sqft, opened_month;
